package pt.crownledger.domain;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static pt.crownledger.domain.Treasury.Currency.*;

class LoansTest {
    final UUID citizen=UUID.randomUUID(),king=UUID.randomUUID(),other=UUID.randomUUID();
    final Loans bank=new Loans();final Treasury treasury=new Treasury();
    final Loans.Limits limits=new Loans.Limits(100_000,2500,12,30,2*Loans.DAY,7*Loans.DAY,0);
    UUID request(long value){return bank.request(citizen,"Aveline","A workshop",CHRONICLES,value,limits,1000);}
    UUID offer(long value,int interest,int count){treasury.addFunds(CHRONICLES,value,Treasury.Kind.DEPOSIT,king,"Public donations",1000);var id=request(value);bank.offer(treasury,id,king,"Aetherion",interest,count,1,limits,false,2000);return id;}
    UUID active(long value,int interest,int count){var id=offer(value,interest,count);bank.accept(id,citizen,"Aveline",3000);return id;}
    @Test void applicationDoesNotReserveOrCreateMoney(){var id=request(10000);assertEquals(0,treasury.balance(CHRONICLES));assertEquals(Loans.State.REQUESTED,bank.get(id).state());assertEquals(0,bank.get(id).paid());}
    @Test void onlyFundedOffersCanReservePublicMoney(){var id=request(10000);assertThrows(RuntimeException.class,()->bank.offer(treasury,id,king,"King",1000,5,1,limits,false,2000));assertEquals(Loans.State.REQUESTED,bank.get(id).state());assertEquals(0,treasury.balance(CHRONICLES));}
    @Test void approvalFreezesTermsAndReservesExactlyThePrincipal(){var id=offer(10000,1000,5);var l=bank.get(id);assertEquals(11000,l.total());assertEquals(2200,l.installment(1));assertEquals(0,treasury.balance(CHRONICLES));assertEquals(king,l.approver());assertEquals(5,l.installments());}
    @Test void aSecondApprovalCannotReserveTheSamePrincipalTwice(){var id=offer(10000,1000,5);treasury.addFunds(CHRONICLES,50000,Treasury.Kind.DEPOSIT,king,"Other funds",2001);assertThrows(RuntimeException.class,()->bank.offer(treasury,id,king,"King",2000,10,2,limits,false,2002));assertEquals(50000,treasury.balance(CHRONICLES));assertEquals(1000,bank.get(id).interest());}
    @Test void borrowedMoneyStartsOnlyAfterTheBorrowerSigns(){var id=offer(10000,1000,5);assertEquals(0,bank.get(id).signedAt());assertThrows(RuntimeException.class,()->bank.accept(id,other,"Other",3000));bank.accept(id,citizen,"Aveline",3000);assertEquals(3000,bank.get(id).signedAt());assertEquals(3000+Loans.DAY,bank.get(id).nextDueAt());assertThrows(RuntimeException.class,()->bank.accept(id,citizen,"Aveline",3001));}
    @Test void oneOpenApplicationOrDebtPerPlayerAcrossCurrencies(){var id=request(10000);assertThrows(RuntimeException.class,()->bank.request(citizen,"A","",EMERALD,10,limits,2000));bank.close(treasury,id,citizen,"A",false,2000);assertNotNull(bank.request(citizen,"A","",EMERALD,10,limits,3000));}
    @Test void interestNeverCompoundsEvenAfterYearsOfArrears(){var id=active(10000,1000,5);bank.observe(10*365*Loans.DAY);assertEquals(11000,bank.get(id).remaining());assertTrue(bank.get(id).overdue(bank.lastObservedAt()));assertThrows(RuntimeException.class,()->bank.request(citizen,"A","",CHRONICLES,1000,limits,bank.lastObservedAt()));}
    @Test void repaymentsReturnMoneyToTheTreasuryAndAllowEarlyFullSettlement(){var id=active(10000,1000,5);bank.repay(treasury,id,citizen,"A",2200,4000);assertEquals(2200,treasury.balance(CHRONICLES));assertEquals(8800,bank.get(id).remaining());bank.repay(treasury,id,citizen,"A",8800,5000);assertEquals(11000,treasury.balance(CHRONICLES));assertEquals(Loans.State.SETTLED,bank.get(id).state());assertEquals(0,bank.get(id).remaining());assertThrows(RuntimeException.class,()->bank.repay(treasury,id,citizen,"A",8800,5001));}
    @Test void installmentRemaindersSumToTheExactFrozenTotal(){var id=active(10001,1750,7);var l=bank.get(id);long sum=0;for(int i=1;i<=7;i++)sum+=l.installment(i);assertEquals(l.total(),sum);for(int i=0;i<7;i++)bank.repay(treasury,id,citizen,"A",bank.payment(id,citizen,false),4000+i);assertEquals(l.total(),treasury.balance(CHRONICLES));assertEquals(Loans.State.SETTLED,bank.get(id).state());}
    @Test void interestRoundsHalfUpOnceInTheCurrencySmallestUnit(){assertEquals(1,Loans.total(1,4999));assertEquals(2,Loans.total(1,5000));assertEquals(115,Loans.total(100,1500));}
    @Test void noZeroInstallmentsOrUnboundedTerms(){var id=request(1);treasury.addFunds(CHRONICLES,1,Treasury.Kind.DEPOSIT,king,"Money",0);assertThrows(RuntimeException.class,()->bank.offer(treasury,id,king,"K",0,2,1,limits,false,2000));assertEquals(1,treasury.balance(CHRONICLES));for(int[] terms:List.of(new int[]{2501,1,1},new int[]{0,13,1},new int[]{0,1,31},new int[]{-1,1,1},new int[]{0,0,1}))assertThrows(RuntimeException.class,()->bank.offer(treasury,id,king,"K",terms[0],terms[1],terms[2],limits,false,2000));}
    @Test void presidentsCannotApproveTheirOwnLoansExceptExplicitEmergency(){var id=request(100);treasury.addFunds(CHRONICLES,100,Treasury.Kind.DEPOSIT,king,"Money",0);assertThrows(RuntimeException.class,()->bank.offer(treasury,id,citizen,"A",0,1,1,limits,false,2000));bank.offer(treasury,id,citizen,"A",0,1,1,limits,true,2000);assertEquals(citizen,bank.get(id).approver());assertEquals("offer",bank.events().getFirst().action());}
    @Test void declinedOrCancelledOffersReturnEscrowOnce(){var id=offer(10000,1000,5);bank.close(treasury,id,citizen,"A",false,3000);assertEquals(10000,treasury.balance(CHRONICLES));assertThrows(RuntimeException.class,()->bank.close(treasury,id,citizen,"A",false,3001));assertEquals(10000,treasury.balance(CHRONICLES));}
    @Test void expiredOffersReturnEscrowWithoutAPlayerOnline(){var id=offer(10000,1000,5);long expiry=bank.get(id).expiresAt();assertTrue(bank.expire(treasury,expiry));assertEquals(Loans.State.EXPIRED,bank.get(id).state());assertEquals(10000,treasury.balance(CHRONICLES));assertFalse(bank.expire(treasury,expiry+1));}
    @Test void nobodyCanCancelOrRewriteAnActiveDebt(){var id=active(10000,1000,5);assertThrows(RuntimeException.class,()->bank.close(treasury,id,king,"K",true,4000));assertThrows(RuntimeException.class,()->bank.close(treasury,id,citizen,"A",false,4000));assertThrows(RuntimeException.class,()->bank.offer(treasury,id,king,"K",0,1,1,limits,false,4000));assertEquals(11000,bank.get(id).remaining());}
    @Test void anotherPlayerCannotPayOrCancelThisContract(){var id=active(10000,1000,5);assertThrows(RuntimeException.class,()->bank.payment(id,other,true));assertThrows(RuntimeException.class,()->bank.repay(treasury,id,other,"Other",2200,4000));assertEquals(0,treasury.balance(CHRONICLES));}
    @Test void restoredContractsKeepOutstandingAmountDatesAndFrozenInterest(){var id=active(10000,1000,5);bank.repay(treasury,id,citizen,"A",2200,4000);var restored=new Loans(bank.snapshot());assertEquals(bank.get(id),restored.get(id));assertEquals(8800,restored.get(id).remaining());assertEquals(3000+2*Loans.DAY,restored.get(id).nextDueAt());assertEquals(bank.events(),restored.events());}
    @Test void clockRollbackCannotDelayExistingDueDatesOrRegenerateRequests(){var id=active(10000,1000,5);bank.observe(10*Loans.DAY);assertEquals(10*Loans.DAY,bank.observe(0));assertTrue(bank.get(id).overdue(bank.lastObservedAt()));assertEquals(11000,bank.get(id).total());}
    @Test void requestCooldownSurvivesClosingAndReconstructingTheBook(){var l=new Loans.Limits(1000,2500,12,30,Loans.DAY,Loans.DAY,60000);var id=bank.request(citizen,"A","",EMERALD,10,l,1000);bank.close(treasury,id,citizen,"A",false,2000);var restored=bank.copy();assertThrows(RuntimeException.class,()->restored.request(citizen,"A","",EMERALD,10,l,3000));assertNotNull(restored.request(citizen,"A","",EMERALD,10,l,61000));}
    @Test void snapshotsAreImmutableAndDuplicateOpenDebtsAreRejected(){var id=request(100);assertThrows(UnsupportedOperationException.class,()->bank.snapshot().loans().clear());var loan=bank.get(id);UUID id2=UUID.randomUUID();var duplicate=new Loans.Loan(id2,loan.borrower(),loan.name(),loan.purpose(),loan.currency(),loan.principal(),loan.state(),loan.requestedAt(),0,loan.expiresAt(),null,"",0,0,0,0,0,0);assertThrows(RuntimeException.class,()->new Loans(new Loans.Snapshot(Map.of(id,loan,id2,duplicate),List.of(),1000)));}
    @Test void alreadyExpiredOrStaleOffersCannotBeSigned(){var id=offer(10000,1000,5);assertThrows(RuntimeException.class,()->bank.accept(id,citizen,"A",bank.get(id).expiresAt()));assertEquals(Loans.State.OFFERED,bank.get(id).state());}
    @Test void invalidTextAndNegativePrincipalNeverCreateApplications(){for(String bad:List.of("§aFake","a\nb","x".repeat(161)))assertThrows(RuntimeException.class,()->bank.request(citizen,"A",bad,EMERALD,10,limits,1000));for(long value:new long[]{-1,0,100001})assertThrows(RuntimeException.class,()->request(value));assertTrue(bank.all().isEmpty());}
}
